 "content": "from collections import deque

def transform(grid):
    """Fill fully enclosed background regions in the line drawing with 4."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if g[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if g[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg and (r,c) not in outside:
                g[r][c] = 4
    return g
